for(const col of ['A','B']){const s=(resumo.match(new RegExp('<'+pr+'c\b(?=[^>]*\br="'+col+'16")[^>]*\bs="(\d+)"'))||[])[1];if(s)resumo=resumo.replace(new RegExp('(<'+pr+'c\b(?=[^>]*\br="'+col+'17")[^>]*\bs=")\d+'),'$1'+s);}
