if(new RegExp('</'+pb+'definedNames>').test(book))book=book.replace(new RegExp('</'+pb+'definedNames>'),names+'</'+pb+'definedNames>');
else book=book.replace(new RegExp('</'+pb+'sheets>'),'$&<'+pb+'definedNames>'+names+'</'+pb+'definedNames>');
write('xl/workbook.xml',book);
for(const [path,xml,p] of [['xl/worksheets/sheet1.xml',resumo,pr],['xl/worksheets/sheet2.xml',oportunidades,po]]){
 let s=xml;
 const setup='<'+p+'pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>';
 if(new RegExp('<'+p+'pageSetup\\b').test(s))s=s.replace(new RegExp('<'+p+'pageSetup\\b[^>]*/>'),setup);
 else s=s.replace(new RegExp('(<'+p+'tableParts\\b|</'+p+'worksheet>)'),setup+'$1');
 s=s.replace(new RegExp('</'+p+'sheetPr>'),'<'+p+'pageSetUpPr fitToPage="1"/></'+p+'sheetPr>');
 write(path,s);
}
for(let i=0;i<zip.FullPaths.length;i++)if(/\/xl\/tables\/[^/]+\.xml$/.test(zip.FullPaths[i])){
 const e=zip.FileIndex[i]; let x=Buffer.from(e.content).toString('utf8');
 if(x.includes('TabelaOportunidades')){x=x.replace(/\bref="A8:R\d+"/g,'ref="A8:R'+fim+'"');e.content=Buffer.from(x);e.size=e.content.length;}
}
const bin=Buffer.from(CFB.write(zip,{type:'buffer',fileType:'zip',compression:true}));
const check=XLSX.read(bin,{type:'buffer'});
if(check.Sheets['Resumo semanal']?.A8?.v!==itens.length)throw new Error('Falha na validação da quantidade de oportunidades.');
const fileName='Relatório semanal de oportunidades - '+todayBr.replaceAll('/','.')+'.xlsx';
return [{json:{quantidadeOportunidades:itens.length,fileName,modeloPreservado:true,registrosSemData:itens.length-datas.length},binary:{data:await this.helpers.prepareBinaryData(bin,fileName,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}}];

// Busca editais com proposta aberta no PNCP (API de busca, até 500 por página).
// Cada requisição que falhar é repetida após 3, 8, 15, 30 e 45 s. O task runner encerra
// nós Code com mais de 300 s, então o tempo por UF (uma execução por UF) é limitado a 240 s.
const inicio = Date.now(), orcamento = 240000;
const espera = ms => new Promise(r => setTimeout(r, ms));
const restante = () => orcamento - (Date.now() - inicio);
const buscar = async (uf, modalidade, pagina, tam) => {
  let ultimoErro = new Error('Tempo limite da busca esgotado');
  for (const ms of [0, 3000, 8000, 15000, 30000, 45000]) {
    if (restante() < ms + 5000) break;
    if (ms) await espera(ms);
    try {
      return await this.helpers.httpRequest({
        url: 'https://pncp.gov.br/api/search/',
        qs: { tipos_documento: 'edital', ordenacao: '-data', status: 'recebendo_proposta', ufs: uf, modalidades: modalidade, pagina, tam_pagina: tam },
        json: true, timeout: 30000,
      });
    } catch (e) { ultimoErro = e; }
  }
  throw ultimoErro;
};
const saida = [];
for (const { json: b } of $input.all()) {
  let paginas;
  try {
    const r = await buscar(b.uf, b.modalidade, 1, 1);
    paginas = Math.max(1, Math.ceil((Number(r.total) || 0) / 500));
  } catch (e) {
    saida.push({ json: { uf: b.uf, pagina: 0, error: { message: e.message } } });
    continue;
  }
  for (let pagina = 1; pagina <= paginas; pagina++) {
    await espera(1500);
    try {
      const r = await buscar(b.uf, b.modalidade, pagina, 500);
      saida.push({ json: { uf: b.uf, pagina, items: r.items || [] } });
    } catch (e) {
      saida.push({ json: { uf: b.uf, pagina, error: { message: e.message } } });
    }
  }
}
return saida;

// Consulta reserva: para cada UF em que a busca do PNCP falhou, baixa as contratações com
// proposta aberta pela API oficial de consulta (50 por página) e converte para o formato da busca.
// O task runner encerra nós Code com mais de 300 s, então o tempo total é limitado a 240 s.
const inicio = Date.now(), orcamento = 240000;
const espera = ms => new Promise(r => setTimeout(r, ms));
const restante = () => orcamento - (Date.now() - inicio);
const paginas = $input.all();
const ufsComFalha = [...new Set(paginas.filter(p => p.json.error).map(p => p.json.uf).filter(Boolean))];
if (!ufsComFalha.length) return paginas;

const busca = Object.fromEntries($('Configurar busca').all().map(i => [i.json.uf, i.json]));
const consultar = async (b, pagina) => {
  let ultimoErro = new Error('Tempo limite da consulta reserva esgotado');
  for (const ms of [0, 3000, 8000, 15000]) {
    if (restante() < ms + 5000) break;
    if (ms) await espera(ms);
    try {
      const r = await this.helpers.httpRequest({
        url: 'https://pncp.gov.br/api/consulta/v1/contratacoes/proposta',
        qs: { dataFinal: b.dataFinal, codigoModalidadeContratacao: b.modalidade, uf: b.uf, pagina, tamanhoPagina: 50 },
        json: true, timeout: 30000, returnFullResponse: true,
      });
      return r.statusCode === 204 || !r.body ? { data: [], paginasRestantes: 0 } : r.body;
    } catch (e) { ultimoErro = e; }
  }
  throw ultimoErro;
};
const converter = p => ({
  uf: p.unidadeOrgao?.ufSigla, orgao_cnpj: p.orgaoEntidade?.cnpj, orgao_nome: p.orgaoEntidade?.razaoSocial,
  ano: p.anoCompra, numero_sequencial: p.sequencialCompra, numero: p.numeroCompra, numero_controle_pncp: p.numeroControlePNCP,
  description: p.objetoCompra, unidade_nome: p.unidadeOrgao?.nomeUnidade, unidade_codigo: p.unidadeOrgao?.codigoUnidade,
  modalidade_licitacao_nome: p.modalidadeNome, data_publicacao_pncp: p.dataPublicacaoPncp,
  data_inicio_vigencia: p.dataAberturaProposta, data_fim_vigencia: p.dataEncerramentoProposta, cancelado: false,
});

const recuperadas = new Set(), extras = [];
for (const uf of ufsComFalha) {
  const b = busca[uf];
  if (!b) continue;
  const itens = [];
  let completa = false;
  try {
    for (let pagina = 1; ; pagina++) {
      if (restante() < 5000) break;
      const r = await consultar(b, pagina);
      itens.push(...(r.data || []).map(converter));
      if (!r.paginasRestantes) { completa = true; break; }
      await espera(1500);
    }
  } catch (e) { /* mantém o aviso de falha para esta UF */ }
  if (itens.length) extras.push({ json: { uf, pagina: 'reserva', items: itens } });
  if (completa) recuperadas.add(uf);
}
// UFs recuperadas por completo deixam de constar como falha; as demais mantêm o aviso.
return [...paginas.filter(p => !(p.json.error && recuperadas.has(p.json.uf))), ...extras];

// Completa processo, número da compra e link do sistema de origem com o detalhe da compra no PNCP.
// Roda em lotes (Loop de detalhes); cada requisição que falhar é repetida após 3 e 8 s.
// O ritmo de uma consulta a cada 2,5 s evita o bloqueio por excesso de requisições.
const espera = ms => new Promise(r => setTimeout(r, ms));
const inicio = Date.now(), orcamento = 200000;
const saida = [];
for (const item of $input.all()) {
  const linha = { ...item.json };
  if (linha._cnpj && Date.now() - inicio < orcamento) {
    for (const ms of [0, 3000, 8000]) {
      if (Date.now() - inicio + ms > orcamento + 30000) break;
      if (ms) await espera(ms);
      try {
        // O tempo de cada consulta nunca passa do limite do lote.
        const timeout = Math.max(5000, Math.min(20000, orcamento + 50000 - (Date.now() - inicio)));
        const d = await this.helpers.httpRequest({ url: 'https://pncp.gov.br/api/consulta/v1/orgaos/' + linha._cnpj + '/compras/' + linha._ano + '/' + linha._seq, json: true, timeout });
        if (d?.processo) linha['Número do processo'] = d.processo;
        if (d?.numeroCompra) linha['Número do edital/compra'] = d.numeroCompra;
        if (d?.linkSistemaOrigem) linha['Link do sistema de origem'] = d.linkSistemaOrigem;
        break;
      } catch (e) { /* tenta de novo; se não der, a linha segue com os dados da busca */ }
    }
    await espera(2500);
  }
  saida.push({ json: linha });
}
return saida;

// Baixa todos os documentos publicados no PNCP (edital, anexos, termo de referência etc.) de cada processo em
// PREGÕES_2026/<UF>/<DD.MM.AAAA - HHhMM - ÓRGÃO - PE Nº>/, usando a data e o horário da sessão (encerramento das propostas).
// Arquivos que já existem na pasta não são baixados de novo, então uma execução seguinte completa o que faltou.
// Roda em lotes (Loop de documentos) e limita o tempo por lote porque o task runner encerra nós Code com mais de 300 s.
const fs = require('fs');
const raiz = '/files/PREGÕES_2026';
const inicio = Date.now(), orcamento = 240000;
const espera = ms => new Promise(r => setTimeout(r, ms));
const restante = () => orcamento - (Date.now() - inicio);
const limpar = v => String(v ?? '').normalize('NFC').replace(/[\\/:*?"<>|\x00-\x1F]/g, ' ').replace(/\s+/g, ' ').trim().replace(/[. ]+$/, '');
const pedir = async opcoes => {
  let ultimoErro = new Error('Tempo do lote esgotado');
  for (const ms of [0, 3000, 8000]) {
    if (restante() < ms + 15000) break;
    if (ms) await espera(ms);
    // O tempo de cada requisição nunca passa do que resta do orçamento do lote.
    const timeout = Math.min(opcoes.timeout || 60000, restante() - 5000);
    try { return await this.helpers.httpRequest({ ...opcoes, timeout }); } catch (e) { ultimoErro = e; }
  }
  throw ultimoErro;
};
const extensaoPorTipo = { 'application/pdf': 'pdf', 'application/zip': 'zip', 'application/x-zip-compressed': 'zip', 'application/msword': 'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx', 'application/vnd.ms-excel': 'xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx', 'application/vnd.oasis.opendocument.text': 'odt',
  'application/vnd.oasis.opendocument.spreadsheet': 'ods', 'application/x-rar-compressed': 'rar', 'application/vnd.rar': 'rar',
  'application/x-7z-compressed': '7z', 'text/plain': 'txt', 'text/csv': 'csv', 'image/jpeg': 'jpg', 'image/png': 'png' };
const nomeDoServidor = cabecalho => {
  const c = String(cabecalho || '');
  const utf8 = c.match(/filename\*\s*=\s*UTF-8''([^;]+)/i);
  if (utf8) { try { return decodeURIComponent(utf8[1].replace(/"/g, '')); } catch (e) { /* usa o nome simples */ } }
  const simples = c.match(/filename\s*=\s*"?([^";]+)"?/i);
  return simples ? Buffer.from(simples[1], 'latin1').toString('utf8') : '';
};
const extensaoDe = nome => (String(nome).match(/\.([A-Za-z0-9]{2,5})$/) || [])[1]?.toLowerCase() || '';
const dataHora = iso => {
  if (!iso) return 'SEM DATA - SEM HORARIO';
  const p = Object.fromEntries(new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false })
    .formatToParts(new Date(iso)).map(x => [x.type, x.value]));
  return p.day + '.' + p.month + '.' + p.year + ' - ' + p.hour + 'H' + p.minute;
};

const saida = [];
for (const { json: p } of $input.all()) {
  if (!p._cnpj) continue;
  // Número no formato 104.2026: troca barras por pontos, inclui o ano se faltar e remove ano repetido.
  // Tira prefixos como "PE" ou "Pregão Eletrônico nº" que alguns órgãos já colocam no número.
  let numero = limpar(String(p['Número do edital/compra'] || p._seq).replace(/\//g, '.'))
    .replace(/^(PE|PREG[AÃ]O(\s+ELETR[OÔ]NICO)?)\s*(N[º°O]?\.?)?\s*/i, '') || String(p._seq);
  if (!/\.\d{4}$/.test(numero)) numero += '.' + p._ano;
  numero = numero.replace(/(\.\d{4})\1+$/, '$1');
  // Encurta só o nome do órgão, para data, horário e número do pregão nunca serem cortados.
  const inicioNome = dataHora(p._prazo) + ' - ', fimNome = ' - PE ' + numero;
  const orgao = limpar(p['Órgão']).slice(0, Math.max(20, 110 - inicioNome.length - fimNome.length)).trim();
  const pasta = raiz + '/' + p.UF + '/' + limpar(inicioNome + orgao + fimNome);
  const resumo = { UF: p.UF, pasta: pasta.replace('/files/', ''), documentos: 0, baixados: 0, jaExistiam: 0, falhas: 0 };
  if (restante() < 30000) { saida.push({ json: { ...resumo, situacao: 'adiado para a próxima execução' } }); continue; }
  let docs;
  try {
    docs = await pedir({ url: 'https://pncp.gov.br/api/pncp/v1/orgaos/' + p._cnpj + '/compras/' + p._ano + '/' + p._seq + '/arquivos', json: true, timeout: 30000 });
  } catch (e) {
    saida.push({ json: { ...resumo, situacao: 'falha ao listar documentos: ' + e.message } });
    continue;
  }
  docs = (Array.isArray(docs) ? docs : docs?.data || []).filter(d => d.statusAtivo !== false && (d.url || d.uri));
  resumo.documentos = docs.length;
  if (!docs.length) { saida.push({ json: { ...resumo, situacao: 'sem documentos publicados' } }); continue; }
  fs.mkdirSync(pasta, { recursive: true });
  const existentes = fs.readdirSync(pasta);
  const usados = new Map();
  for (const [indice, d] of docs.entries()) {
    let base = limpar(d.titulo || d.tipoDocumentoNome || 'Documento ' + (indice + 1)).slice(0, 90).trim() || 'Documento ' + (indice + 1);
    const extTitulo = extensaoDe(base);
    if (extTitulo) base = base.slice(0, -(extTitulo.length + 1)).trim();
    const repeticoes = (usados.get(base) || 0) + 1;
    usados.set(base, repeticoes);
    if (repeticoes > 1) base += ' (' + repeticoes + ')';
    if (existentes.some(f => f === base || f.startsWith(base + '.'))) { resumo.jaExistiam++; continue; }
    if (restante() < 30000) { resumo.falhas++; continue; }
    await espera(2500);
    try {
      const r = await pedir({ url: d.url || d.uri, encoding: 'arraybuffer', returnFullResponse: true, timeout: 120000 });
      const tipo = String(r.headers?.['content-type'] || '').split(';')[0].trim().toLowerCase();
      const ext = extTitulo || extensaoDe(nomeDoServidor(r.headers?.['content-disposition'])) || extensaoPorTipo[tipo] || 'pdf';
      fs.writeFileSync(pasta + '/' + base + '.' + ext, Buffer.from(r.body));
      resumo.baixados++;
    } catch (e) { resumo.falhas++; }
  }
  if (!fs.readdirSync(pasta).length) fs.rmdirSync(pasta);
  saida.push({ json: { ...resumo, situacao: resumo.falhas ? 'incompleto (será completado na próxima execução)' : 'ok' } });
}
return saida.length ? saida : [{ json: { situacao: 'nenhum processo neste lote' } }];
